function customerAccountSummary(d,c){
 const docs=d.documents.filter(x=>x.customerId===c.id),sales=docs.filter(x=>x.documentType==='sale'),returns=docs.filter(x=>x.documentType==='sale_return'),settlements=d.settlements.filter(x=>sales.some(s=>s.id===x.documentId));
 const paid=new Map(),balance=new Map(),add=(map,currency,amount)=>map.set(currency,(map.get(currency)||0)+Number(amount||0));
 for(const row of c.openingBalances||[])add(balance,row.currency||'IQD',row.amount);
 for(const row of sales){add(balance,row.currency||'IQD',row.dueAmount);add(paid,row.currency||'IQD',row.paidAmount)}
 for(const row of returns)add(balance,row.currency||'IQD',-Number(row.dueAmount));
 for(const row of settlements){const currency=row.currency||sales.find(s=>s.id===row.documentId)?.currency||'IQD';add(balance,currency,-row.amount);add(paid,currency,row.amount)}
 const movementDates=[...docs.map(x=>x.occurredAt),...(c.openingBalances||[]).map(x=>x.occurredAt)].filter(Boolean).sort();
 const payments=[...sales.filter(x=>Number(x.paidAmount)>0).map(x=>({at:x.occurredAt,amount:x.paidAmount,currency:x.currency||'IQD'})),...settlements.map(x=>({at:x.occurredAt||x.createdAt,amount:x.amount,currency:x.currency||sales.find(s=>s.id===x.documentId)?.currency||'IQD'}))].sort((a,b)=>(b.at||'').localeCompare(a.at||''));
 const currencyName=x=>x==='USD'?'دولار':x==='IQD'?'د.ع':esc(x),moneyRows=map=>[...map].map(([currency,amount])=>money(Math.abs(amount))+' '+currencyName(currency)).join(' · ')||'0 د.ع';
 return '<div class="customer-account-summary"><div><span>آخر حركة</span><b>'+datetime(movementDates.at(-1))+'</b></div><div><span>آخر تسديد</span><b>'+datetime(payments[0]?.at)+'</b></div><div><span>مبلغ آخر تسديد</span><b>'+(payments[0]?money(payments[0].amount)+' '+currencyName(payments[0].currency):'—')+'</b></div><div><span>المبلغ المدفوع</span><b>'+moneyRows(paid)+'</b></div><div><span>المتبقي</span><b>'+[...balance].map(([currency,amount])=>(amount>0?'عليه ':'له ')+money(Math.abs(amount))+' '+currencyName(currency)).join(' · ')||'0 د.ع'+'</b></div></div>';
}
